def _mk(d):
    os.makedirs(d, exist_ok=True)
    return d


def fpath(split, lv, cond):
    if split == "dev" and cond in OLD_CONDS:
        return f"{FIX.REL_DEV}/{lv}/l1_{cond}.npz"
    if split == "dev" and cond == "nolab":
        return os.path.join(F5.OUT, "dev", lv, "l1_nolab.npz")
    return os.path.join(OUT, split, lv, f"l1_{cond}.npz")


def grid(split):
    """The matched groups of the split's main body (review 2: test-like splits carry unseen subsets, which the noise
    renderer leaves out and dev does not have; they stay out of this confirmation)."""
    rows, rows_by = G.load(split)
    groups = [g for g in G.load_groups(split) if rows_by[(g["unit"], "1")].get("subset") is None]
    keys = {(g["unit"], v, g["k"]) for g in groups for v in g["versions"]}
    wins = [w for w in D.windows_of(rows, split) if (w["unit"], w["version"], w["k"]) in keys]
    return rows, rows_by, groups, wins


def contexts(split, groups, rows_by):
    final = split != "dev"
    M = G.matched_context(C.Context)
    ctx = {c: M(split, groups, c, rows_by, final=final) for c in ("none", "c0.99", "mv0.99", "c0.5", "mv0.5")}
    ctx["truth"] = RD.truth_context(C.Context)(split, groups, "truth", rows_by, final=final)

    class NoLab(M):                      # = p1v4_reliability_fix5.dev_nolab_context, for any split
        def point(self, r, k):
            tr, sc, tags, snd = super().point(r, k)
            return tr, sc, tags, [s for s in snd if s[0] not in F5.DROP]

    ctx["nolab"] = NoLab(split, groups, "none", rows_by, final=final)
    return ctx


