def render(split, variants):
    for v in variants:
        if v not in NEW_DB:
            raise SystemExit(f"{v}: only {sorted(NEW_DB)} are rendered here")
    if split == "dev":
        raise SystemExit("dev variants were rendered by step 1 (scripts/p1v4_reliability_dev.py render)")
    import p1v4_freeze as FZ
    FZ.verify_or_stop()                                   # the freeze record must hold before anything is rendered
    NF.VARIANTS = dict(NF.VARIANTS, **NEW_DB)
    NF.frozen = lambda s: FZ.verify_or_stop()["settings"]  # amendment: +20/+30/+40 dB added for this confirmation
    NF.out_dir = lambda s, variant, *sub: _mk(os.path.join(OUT, s, "render", variant, *sub))
    for v in variants:
        if os.path.exists(os.path.join(D.RENDER, f"{split}_{v}", "meta.jsonl")):
            print(f"{split}_{v}: exists, skipped", flush=True)
            continue
        t0 = time.time()
        NF.render(split, v)
        print(f"{split}_{v} rendered in {time.time() - t0:.0f} s", flush=True)


# ------------------------------------------------------------------------------------------------ forward

WORKERS = 6                                              # processes that build the situation texts (CPU-bound)
_W = {}


def _winit(split):
    NF.patch_folders()
    rows, rows_by, groups, wins = grid(split)
    _W.update(rows_by=rows_by, part_of={g["unit"]: g["part"] for g in groups},
              ctx=contexts(split, groups, rows_by), wins={w["id"]: w for w in wins})


def _texts(job):
    import p1v4_readout as RO
    cond, ids = job
    out = []
    for wid in ids:
        w = _W["wins"][wid]
        r = _W["rows_by"][(w["unit"], w["version"])]
        text, asks = _W["ctx"][cond].situation(r, w["k"], "full")
        qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
        snd = [s for s in _W["ctx"][cond].point(r, w["k"])[3] if RO.in_window(s, w["t"])]
        out.append({"id": w["id"], "unit": w["unit"], "part": _W["part_of"][w["unit"]],
                    "key": (w["unit"], w["version"], w["k"]), "text": text,
                    "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                    "gold": [-1 if w["gold"].get(q) is None else
                             int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs],
                    "real": RO.is_real(r, w["t"]), "conf": max([s[3] for s in snd], default=-1.0)})
    return out


def build_texts(split, conds, wins, part_of, workers=WORKERS):
    """{cond: [item]} in window order, built in `workers` processes (each loads the split's front end once)."""
    import concurrent.futures as cf
    want = {c: [w["id"] for w in wins if not (c in ONLY and ONLY[c] != part_of[w["unit"]])] for c in conds}
    jobs = [(c, ids[i:i + 200]) for c, ids in want.items() for i in range(0, len(ids), 200)]
    t0 = time.time()
    if workers <= 1:
        _winit(split)
        res = [_texts(j) for j in jobs]
    else:
        with cf.ProcessPoolExecutor(max_workers=workers, initializer=_winit, initargs=(split,)) as ex:
            res = list(ex.map(_texts, jobs))
    out = {c: [] for c in conds}
    for (c, _), items in zip(jobs, res):
        out[c] += items
    for c in conds:
        assert [it["id"] for it in out[c]] == want[c], f"{c}: text order differs from the window order"
    print(f"{split}: texts of {', '.join(conds)} built in {time.time() - t0:.0f} s ({workers} processes)",
          flush=True)
    return out


def check_texts(split="dev"):
    """The parallel texts must equal the texts of the stored dev forwards (text_sha), condition by condition."""
    rows, rows_by, groups, wins = grid(split)
    part_of = {g["unit"]: g["part"] for g in groups}
    conds = ("none", "c0.99", "mv0.99", "truth", "c0.5", "mv0.5", "nolab")
    texts = build_texts(split, conds, wins, part_of)
    worst = {}
    for c in conds:
        z = np.load(fpath(split, "dclean", c))
        stored = dict(zip(z["ids"].astype(str), z["text_sha"].astype(str)))
        new = {it["id"]: G.sha(it["text"]) for it in texts[c]}
        worst[c] = {"windows": len(new), "stored": len(stored),
                    "different": sum(new.get(i) != s for i, s in stored.items())}
    print(json.dumps(worst))
    assert all(v["different"] == 0 and v["windows"] == v["stored"] for v in worst.values()), "texts differ"


def forward(split, conds=None, levels=LEVELS, out=None):
    """out None: the run's files (fpath); out = a folder: the dev rehearsal (review 9) writes <out>/<lv>/l1_<c>.npz."""
    import soundfile as sf
    import torch
    import p1v4_readout as RO
    from p1v4_readout_2d import per_second
    D.gpu_guard()
    NF.patch_folders()

    def opath(lv, c):
        return fpath(split, lv, c) if out is None else os.path.join(out, lv, f"l1_{c}.npz")

    rows, rows_by, groups, wins = grid(split)
    part_of = {g["unit"]: g["part"] for g in groups}
    keys = {(w["unit"], w["version"], w["k"]) for w in wins}
    paths = {"dclean": {(w["unit"], w["version"], w["k"]): w["path"] for w in wins}}
    for lv in levels:
        if lv == "dclean":
            continue
        folder = f"{split}_{lv}"
        if not os.path.exists(os.path.join(D.RENDER, folder, "meta.jsonl")):
            raise SystemExit(f"{folder} is not rendered")
        rv = D.load_rows(folder)
        paths[lv] = {(w["unit"], w["version"], w["k"]): w["path"] for w in D.windows_of(rv, folder)
                     if (w["unit"], w["version"], w["k"]) in keys}
        if set(paths[lv]) != keys:
            raise SystemExit(f"{folder}: {len(keys - set(paths[lv]))} group windows missing")
    if conds is None:
        conds = NEW_CONDS if split == "dev" else ALL_CONDS
    log = {}
    todo_c = [c for c in conds if any(not os.path.exists(opath(lv, c)) for lv in levels)]
    texts = (build_texts(split, todo_c, wins, part_of, workers=WORKERS if split == "dev" else 1)
             if todo_c else {})                          # the text does not depend on the level (review 12: 1 process)
    model = F3._model()
    for cond in conds:                                   # "none" first: the other conditions copy its per-second ears
        todo = [lv for lv in levels if not os.path.exists(opath(lv, cond))]
        if not todo:
            print(f"{split}/{cond}: every level exists, skipped", flush=True)
            continue
        base = texts[cond]
        for lv in todo:
            path = opath(lv, cond)
            _mk(os.path.dirname(path))
            ref = None if cond == "none" else dict(np.load(opath(lv, "none")))   # its per-second ears by id
            rpos = None if ref is None else {str(i): n for n, i in enumerate(ref["ids"])}
            items = [dict(it, path=paths[lv][it["key"]]) for it in base]
            H, E, SM, SX, QW, QT, QG, PO = [], [], [], [], [], [], [], []
            t0 = time.time()
            with torch.no_grad():
                for i, it in enumerate(items):                       # batch 1, as steps 1 and 5
                    wave = torch.from_numpy(sf.read(it["path"], dtype="float32")[0])[None].cuda()
                    h, e, qw, po = RO.forward_states(model, wave, [it["text"]], [it["marker"]],
                                                     [[RO.TASK[q] for q in it["qs"]]])
                    if ref is None:
                        sm, sx, _ = per_second(model.vt, wave)
                    else:                                            # the audio is the same as in "none"
                        sm, sx = ref["sec_mean"][rpos[it["id"]]][None], ref["sec_max"][rpos[it["id"]]][None]
                    H.append(h.astype(np.float16))
                    E.append(e.astype(np.float16))
                    SM.append(np.asarray(sm).astype(np.float16))
                    SX.append(np.asarray(sx).astype(np.float16))
                    QW.append(qw + i)
                    QT += it["qs"]
                    QG += it["gold"]
                    PO.append(po)
                    if (i + 1) % 500 == 0:
                        print(f"  {split}/{lv}/{cond}: {i + 1}/{len(items)} windows {time.time() - t0:.0f} s",
                              flush=True)
            z = dict(states=np.concatenate(H), ears=np.concatenate(E), sec_mean=np.concatenate(SM),
                     sec_max=np.concatenate(SX), q_win=np.concatenate(QW), q_task=np.array(QT), q_gold=np.array(QG),
                     p_old=np.concatenate(PO), ids=np.array([it["id"] for it in items]),
                     units=np.array([it["unit"] for it in items]), parts=np.array([it["part"] for it in items]),
                     real=np.array([it["real"] for it in items]), conf=np.array([it["conf"] for it in items]),
                     text_sha=np.array([G.sha(it["text"]) for it in items]))
            tmp = path + ".tmp.npz"
            np.savez(tmp, **z)
            os.replace(tmp, path)
            log[f"{lv}/{cond}"] = {"windows": len(items), "questions": len(QT), "seconds": round(time.time() - t0)}
            print(f"{split}/{lv}/{cond} done: {len(items)} windows, {len(QT)} questions, {time.time() - t0:.0f} s",
                  flush=True)
    lp = os.path.join(_mk(os.path.join(OUT, split) if out is None else out), "forward_log.json")
    old = json.load(open(lp)) if os.path.exists(lp) else {}
    json.dump(dict(old, **log), open(lp, "w"), indent=1)


