def rehearse():
    """Review 9, dev only: the paths the dev run never took must reproduce step 1 and 5 exactly.
    (a) render: dev at +20 dB into a temporary variant; every window's sha256 equals step 1's dev_dnoise20.
    (b) forward: all seven inputs at the clean level into a rehearsal folder ("none" computes its per-second ears,
        the others copy them); every array equals the stored dev file of that input."""
    import shutil
    rd = os.path.join(OUT, "dev_rehearsal")
    # (a) render
    tmp = os.path.join(D.RENDER, "dev_dnoise20r")
    if os.path.exists(tmp):
        shutil.rmtree(tmp)
    NF.VARIANTS = dict(NF.VARIANTS, dnoise20r=20)
    NF.frozen = lambda s: RD.rehearsal_settings()
    NF.out_dir = lambda s, variant, *sub: _mk(os.path.join(rd, "render", variant, *sub))
    t0 = time.time()
    NF.render("dev", "dnoise20r")
    NF.patch_folders()
    sha = {}
    for name in ("dev_dnoise20", "dev_dnoise20r"):
        for r in D.load_rows(name):
            for p in r["points"]:
                sha.setdefault(name, {})[(r["unit"], r["version"], p["k"])] = p["sha256"]
    same = sum(sha["dev_dnoise20"][k] == v for k, v in sha["dev_dnoise20r"].items())
    rep = {"render": {"windows": len(sha["dev_dnoise20r"]), "stored": len(sha["dev_dnoise20"]), "same_sha256": same,
                      "seconds": round(time.time() - t0)}}
    shutil.rmtree(tmp)
    print("render rehearsal:", json.dumps(rep["render"]), flush=True)
    assert same == len(sha["dev_dnoise20r"]) == len(sha["dev_dnoise20"]), "the render path does not reproduce step 1"
    # (b) forward
    forward("dev", conds=ALL_CONDS, levels=("dclean",), out=rd)
    rep["forward"] = {}
    for c in ALL_CONDS:
        a, b = dict(np.load(os.path.join(rd, "dclean", f"l1_{c}.npz"))), dict(np.load(fpath("dev", "dclean", c)))
        common = [k for k in ("states", "sec_mean", "sec_max", "p_old", "q_win", "q_task", "q_gold", "ids",
                              "text_sha", "ears") if k in a and k in b]
        diff = {}
        for k in common:
            if a[k].dtype.kind in "fc":
                diff[k] = float(np.max(np.abs(a[k].astype(np.float64) - b[k].astype(np.float64)))) \
                    if a[k].shape == b[k].shape else "shape differs"
            else:
                diff[k] = 0.0 if np.array_equal(a[k].astype(str), b[k].astype(str)) else "differs"
        rep["forward"][c] = diff
    json.dump(rep, open(os.path.join(rd, "rehearsal.json"), "w"), indent=1)
    print("forward rehearsal:", json.dumps(rep["forward"]), flush=True)
    assert all(v == 0.0 for d in rep["forward"].values() for v in d.values()), "the forward path does not reproduce"
    print("REHEARSAL PASS", flush=True)


# ------------------------------------------------------------------------------------------------ statistics

def auroc(score, right):
    """AUROC of right vs wrong with average ranks for ties (= p1v4_reliability_fix5.auroc, O(n log n))."""
    from scipy.stats import rankdata
    score, right = np.asarray(score, np.float64), np.asarray(right, bool)
    if right.all() or not right.any():
        return None
    ranks = rankdata(score, method="average")
    npos = right.sum()
    return float((ranks[right].sum() - npos * (npos + 1) / 2) / (npos * (len(score) - npos)))


def acc_fn(sel):
    return float(np.mean([x[6] for x in sel])) if sel else None


def cer_fn(sel):
    cp = [x for x in sel if x[4]]
    return float(np.mean([not x[6] for x in cp])) if cp else None


def share_fn(sel):
    return float(np.mean([x[4] for x in sel])) if sel else None


def boot_joint(sets, fn, seed=SEED, n=N_BOOT, alpha=0.05):
    """Percentile (1 - alpha) interval of fn({name: items}) with units (x[0]) resampled jointly across all sets, as
    [low, high, valid draws] (review 14: draws where fn is undefined are dropped and counted)."""
    by = {k: collections.defaultdict(list) for k in sets}
    units = set()
    for k, items in sets.items():
        for x in items:
            by[k][x[0]].append(x)
            units.add(x[0])
    units = sorted(units)
    rng = np.random.default_rng(seed)
    vals = []
    for _ in range(n):
        pick = rng.integers(0, len(units), len(units))
        v = fn({k: [x for i in pick for x in by[k].get(units[i], ())] for k in sets})
        if v is not None:
            vals.append(v)
    if not vals:
        return None
    return [float(np.quantile(vals, alpha / 2)), float(np.quantile(vals, 1 - alpha / 2)), len(vals)]


def verdict(point, ci, bar, higher, n_conf=None):
    """Reading rule of the registration (section 4): confirmed = the whole interval on the passing side; unclear =
    the point on the passing side, the interval across the bar; not confirmed = the point on the failing side, the
    interval across the bar; contradicted = the whole interval on the failing side (review 7); not evaluable = fewer
    than 30 confident decisions or no interval."""
    if n_conf is not None and n_conf < FEW:
        return "not evaluable"
    if point is None or ci is None:
        return "not evaluable"
    ok = point > bar if higher else point < bar
    if (ci[0] > bar) if higher else (ci[1] < bar):
        return "confirmed"
    if (ci[1] < bar) if higher else (ci[0] > bar):
        return "contradicted"
    return "unclear" if ok else "not confirmed"


# ------------------------------------------------------------------------------------------------ items

def build_items(split):
    """Q[(part, condition, system, level, subset)] = items, as p1v4_reliability_fix5.eval_ (plus the 0.5
    conditions), and the label dependence of every question."""
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    models, m4 = F5.load_models(), F4.load_models()
    th = F4.main_th()
    th5, th4 = models["notification_thresholds"], m4["notification_thresholds"]
    st = RD.rehearsal_settings()
    ths = {"2d": (th["S"], th["R"]), "old head": (st["local"]["L1"]["th_s"], st["local"]["L1"]["th_r"])}
    ro2d, pr = R2D.load_2d(), FIX2.load_probe()
    rows, rows_by, groups, gw = grid(split)
    wins = {w["id"]: w for w in gw}
    cov = {g["unit"]: F3.covered(g, rows_by) for g in groups}
    words = pickle.load(open(os.path.join(F5.OUT, "words.pkl"), "rb"))
    ctx_none = G.matched_context(C.Context)(split, groups, "none", rows_by, final=split != "dev")
    words_of = dict(zip([w["id"] for w in gw], F5.words_p(words, [F5.last_line(ctx_none.situation(
        rows_by[(w["unit"], w["version"])], w["k"], "full")[0]) for w in gw])))
    Q, dep_of = {}, {}

    def subsets(qs, part):
        out = {"all": [x for x in qs if x[1] == part]}
        out["covered"] = [x for x in out["all"] if cov[x[0]]]
        out["not covered"] = [x for x in out["all"] if not cov[x[0]]]
        return {k_: v for k_, v in out.items() if v}

    for lv in LEVELS:
        zs = {c: dict(np.load(fpath(split, lv, c))) for c in OLD_CONDS + NEW_CONDS}
        z0 = dict(np.load(fpath(split, lv, "nolab")))
        sec0 = R2D.Sec(None, z0["ids"], z0["sec_mean"], z0["sec_max"])
        sc0 = RD.keyed(R2D.scores_2d(z0, sec0, ro2d))
        for cond, (on, lab) in COND_SETS.items():
            parts_z = {"none": [zs["none"]], "fake": [zs["c0.99"], zs["mv0.99"]], "truth": [zs["truth"]],
                       "fake05": [zs["c0.5"], zs["mv0.5"]]}[lab]
            qs = {n: [] for n in SYSTEMS}
            for zd in parts_z:
                sec = R2D.Sec(None, zd["ids"], zd["sec_mean"], zd["sec_max"])
                sc_main = RD.keyed(R2D.scores_2d(zd, sec, ro2d))
                for j in range(len(zd["q_task"])):
                    if int(zd["q_gold"][j]) < 0:
                        continue
                    wid = str(zd["ids"][int(zd["q_win"][j])])
                    u, v, k = wid.split("|")
                    q = str(zd["q_task"][j])
                    dep_of[(lv, cond, wid, q)] = float(F5.zrel(sc_main[(u, v, int(k))][q], th[q]) -
                                                       F5.zrel(sc0[(u, v, int(k))][q], th[q]))
                qs["2d"] += F5.items_main(zd, sc_main, ths["2d"])
                qs["old head"] += F3.questions3(zd, RD.keyed(RO.scores_of(zd, None, None)), ths["old head"])
                v4s = {} if on else F5.v4_conf_scores(zd, sc_main, th, m4, pr)
                qs["rel v4"] += [x + (v4s.get((x[7], x[2])),)
                                 for x in F4.items_v4(zd, sc_main, th, m4, th4, on, rows_by, wins, pr)]
                qs["rel v5"] += F5.items5(zd, z0, sc_main, sc0, th, models, th5, on, rows_by, wins, pr, words_of)
                if not on:
                    qs["rel v5 label-free only"] += F5.items5(zd, z0, sc_main, sc0, th, models, th5, False, rows_by,
                                                              wins, pr, words_of, "confidence_label_free_only")
            for n, qq in qs.items():
                for part in ("r_hear", "s_move"):
                    for sub, sel in subsets(qq, part).items():
                        Q[(part, cond, n, lv, sub)] = sel
    return Q, dep_of, wins, {"main": th, "notification model v5": th5, "notification model v4": th4,
                             "old head": {"S": ths["old head"][0], "R": ths["old head"][1]}}


# ------------------------------------------------------------------------------------------------ claims

def candidate_claims(Q, wins):
    """(claims, specs): every candidate statistic with its 95% interval and bar, and the (sets, statistic) that
    resamples it (kept so the key claims' Bonferroni interval can be recomputed, registration 4). The registration
    names which claims are registered (those whose dev interval lies on the passing side)."""
    out, specs = {}, {}

    def put(key, sets, fn, **c):
        specs[key] = (sets, fn)
        c["ci95"] = boot_joint(sets, fn)
        out[key] = c

    def ev_member(x):
        return wins[x[7]]["gold"][x[2]] == ("not" if x[2] == "R" else "stop")

    def diff(f):
        return lambda s: None if f(s["a"]) is None or f(s["b"]) is None else f(s["a"]) - f(s["b"])

    # M: the main system's mirror (step 1), and its confidence without knowing it cannot hear
    for p in ("r_hear", "s_move"):
        for lv in ("dnoise20", "dnoise30", "dnoise40"):
            a, b = Q[(p, "T_off_truth", "2d", lv, "all")], Q[(p, "T_off_truth", "old head", lv, "all")]
            put(f"M1 {p} {lv}: true labels, main minus old head accuracy < -0.05", {"a": a, "b": b}, diff(acc_fn),
                point=acc_fn(a) - acc_fn(b), bar=-0.05, higher=False, main=acc_fn(a), **{"old head": acc_fn(b)})
        for c in ("D_off_none", "C_off_fake", "C05_off_fake"):
            for lv in ("dnoise30", "dnoise40"):
                s_ = Q[(p, c, "2d", lv, "all")]
                put(f"M2 {p} {c} {lv}: main system's confident errors > 0.10", {"a": s_},
                    lambda s: cer_fn(s["a"]), point=cer_fn(s_), bar=0.10, higher=True,
                    n_confident=int(sum(x[4] for x in s_)), confident_share=share_fn(s_))
    # V4: explicit doubt from the clarity signal lowers confident errors (no labels), relative to the main system
    for p in ("r_hear", "s_move"):
        for lv in ("dnoise30", "dnoise40"):
            a, b = Q[(p, "D_off_none", "rel v4", lv, "all")], Q[(p, "D_off_none", "2d", lv, "all")]
            put(f"V4a {p} {lv}: no labels, version 4 minus main confident errors < 0", {"a": a, "b": b},
                diff(cer_fn), point=None if cer_fn(a) is None or cer_fn(b) is None else cer_fn(a) - cer_fn(b),
                bar=0.0, higher=False, n_confident=int(sum(x[4] for x in a)), **{"version 4": cer_fn(a)},
                main=cer_fn(b), confident_share_v4=share_fn(a), confident_share_main=share_fn(b))

    # pooled AUROC (right vs wrong) over the five levels, without notifications
    def pooled(p, c, n):
        return [x for lv in LEVELS for x in Q[(p, c, n, lv, "all")]]

    def au(items):
        return auroc([x[8] for x in items], [x[6] for x in items])

    def au_diff(a, b):
        def f(s):
            ua, ub = au(s["a"]), au(s["b"])
            return None if ua is None or ub is None else ua - ub
        return f

    # direction of each AUROC difference by condition: True = above the bar, False = below, "eq" = within +-bar,
    # None = report only
    fake_up_truth_down = {"C_off_fake": True, "C05_off_fake": True, "T_off_truth": False, "D_off_none": None}
    au_claims = (
        ("V4b", "rel v4", "2d", "version 4 minus main margin AUROC", 0.03,
         {"D_off_none": "eq", "C_off_fake": None, "C05_off_fake": None, "T_off_truth": None}),
        ("V5s", "rel v5", "2d", "version 5 minus main margin AUROC", 0.0, fake_up_truth_down),
        ("TD1", "rel v5", "rel v4", "version 5 minus version 4 AUROC", 0.0, fake_up_truth_down),
        ("TD2", "rel v5 label-free only", "rel v5", "label-free only minus version 5 AUROC", 0.0, fake_up_truth_down))
    for p in ("r_hear", "s_move"):
        for c in ("D_off_none", "C_off_fake", "C05_off_fake", "T_off_truth"):
            sys_items = {n: pooled(p, c, n) for n in ("2d", "rel v4", "rel v5", "rel v5 label-free only")}
            keys = [(x[7], x[2]) for x in sys_items["2d"]]
            assert all(keys == [(x[7], x[2]) for x in v] for v in sys_items.values()), "question order differs"
            for tag, a_, b_, name, bar, direction in au_claims:
                a, b = sys_items[a_], sys_items[b_]
                d = direction[c]
                if tag == "TD1" and p == "s_move" and c in ("C_off_fake", "C05_off_fake"):
                    d = None                             # review 4: equals the no-label difference; report only
                rel = {True: f"> {bar:g}", False: f"< {bar:g}", "eq": f"within +-{bar:g}", None: "(report)"}[d]
                put(f"{tag} {p} {c}: {name} {rel}, pooled over levels", {"a": a, "b": b}, au_diff(a, b),
                    point=au(a) - au(b), bar=bar, higher=d, **{a_: au(a), b_: au(b)})
    # V5: notifications on (covered events), not over-suspicious at clean; knock not covered
    for p in ("r_hear", "s_move"):
        for c, lvs in (("A_on_none", ("dnoise20", "dnoise30", "dnoise40")), ("B_on_fake", LEVELS),
                       ("B05_on_fake", LEVELS)):
            for lv in lvs:
                s_ = Q[(p, c, "rel v5", lv, "covered")]
                ev = [x for x in s_ if ev_member(x)]
                ne = [x for x in s_ if not ev_member(x)]
                put(f"V5n {p} {c} {lv}: notifications on, covered events, accuracy > 0.95", {"a": s_},
                    lambda s: acc_fn(s["a"]), point=acc_fn(s_), bar=0.95, higher=True,
                    **{"event members": acc_fn(ev), "no-event members": acc_fn(ne)}, n=len(s_))
        for c in ("D_off_none", "C_off_fake", "C05_off_fake", "T_off_truth"):   # review 6: label cells added
            a, b = Q[(p, c, "rel v5", "dclean", "all")], Q[(p, c, "2d", "dclean", "all")]
            tag = f" {c}"
            put(f"V5o {p}{tag}: clean, version 5 minus main confident share > -0.10", {"a": a, "b": b},
                diff(share_fn), point=share_fn(a) - share_fn(b), bar=-0.10, higher=True,
                **{"version 5": share_fn(a)}, main=share_fn(b))
    for c in ("A_on_none",):
        for lv in ("dnoise30", "dnoise40"):
            s_ = Q[("r_hear", c, "rel v5", lv, "not covered")]
            put(f"V5k r_hear knock {c} {lv}: notifications on, uncovered knock, confident errors > 0.10", {"a": s_},
                lambda s: cer_fn(s["a"]), point=cer_fn(s_), bar=0.10, higher=True,
                n_confident=int(sum(x[4] for x in s_)))
    return out, specs


def judge_all(cands):
    for k, c in cands.items():
        ci = c["ci95"]
        if c["higher"] is None:
            c["verdict"] = "report"
        elif c["higher"] == "eq":                        # equivalence: the whole interval within +-bar
            c["verdict"] = ("not evaluable" if ci is None or c["point"] is None else
                            "confirmed" if -c["bar"] < ci[0] and ci[1] < c["bar"] else
                            "contradicted" if ci[0] >= c["bar"] or ci[1] <= -c["bar"] else
                            "unclear" if abs(c["point"]) < c["bar"] else "not confirmed")
        else:
            c["verdict"] = verdict(c["point"], ci, c["bar"], c["higher"], c.get("n_confident"))
        if ci is not None and ci[2] < 0.95 * N_BOOT:
            c["few_valid_draws"] = True
    return cands


# ------------------------------------------------------------------------------------------------ eval

def check_files(split):
    """Review 10: every forward file must belong to the current grid and texts (no file of an earlier attempt is
    reused silently): window ids as expected, text hashes equal to freshly built texts, the same windows and
    questions at every level, and the noisy levels' per-second ears different from the clean ones."""
    rows, rows_by, groups, wins = grid(split)
    part_of = {g["unit"]: g["part"] for g in groups}
    texts = build_texts(split, ALL_CONDS, wins, part_of, workers=WORKERS if split == "dev" else 1)
    out = {"groups": dict(collections.Counter(g["part"] for g in groups)), "windows": len(wins)}
    for cond in ALL_CONDS:
        want_ids = [it["id"] for it in texts[cond]]
        want_sha = {it["id"]: G.sha(it["text"]) for it in texts[cond]}
        ref = None
        for lv in LEVELS:
            z = np.load(fpath(split, lv, cond))
            ids = [str(i) for i in z["ids"]]
            assert sorted(ids) == sorted(want_ids), f"{lv}/{cond}: windows differ from the current grid"
            bad = sum(want_sha[i] != str(s) for i, s in zip(ids, z["text_sha"]))
            assert bad == 0, f"{lv}/{cond}: {bad} texts differ from the current texts"
            cur = (ids, list(z["q_task"].astype(str)), list(z["q_gold"]))
            if ref is None:
                ref, sec_clean = cur, z["sec_mean"]
            else:
                assert cur == ref, f"{lv}/{cond}: windows or questions differ from the clean level"
                assert not np.array_equal(z["sec_mean"], sec_clean), f"{lv}/{cond}: same ears as the clean level"
        out[cond] = len(want_ids)
    print("forward files match the grid:", json.dumps(out), flush=True)
    return out


def eval_(split):
    t0 = time.time()
    path = f"results/main_v04/reliability_confirm_{split}.json"
    if split != "dev" and os.path.exists(path):
        raise SystemExit(f"{path} exists: the confirmation result is written once (review 13)")
    files_ok = check_files(split)
    Q, dep_of, wins, ths = build_items(split)
    res = {"split": split, "note": "evidence-reliability confirmation; registration docs/p1_v04_reliability_"
                                   "registration.md", "thresholds": ths, "confident": f"probability of the chosen "
                                                                                       f"answer >= {CONF_P}",
           "grid": files_ok, "cells": {}, "claims": {}, "report": {}}
    if split != "dev":
        res["confirmation_freeze_record"] = json.load(open(FREEZE_OUT))["git_commit"]
    for (part, cond, n, lv, sub), sel in Q.items():
        s_ = F3.stats(sel)
        s_.pop("confident_share_threshold_distance")
        s_.pop("confident_error_rate_threshold_distance")
        s_["group_all_right"] = float(np.mean(list(F3.all_right(sel).values())))
        res["cells"].setdefault(part, {}).setdefault(cond, {}).setdefault(n, {}).setdefault(sub, {})[lv] = s_
    if split == "dev":                                   # reproduce the stored step-4 and step-5 dev cells exactly
        r5 = json.load(open("results/main_v04/reliability_step5_dev.json"))["cells"]
        r4 = json.load(open("results/main_v04/reliability_step4_dev.json"))["cells"]
        worst = 0.0
        for p in ("r_hear", "s_move"):
            for c in r5[p]:
                for n in r5[p][c]:
                    for sub in r5[p][c][n]:
                        for lv, cell in r5[p][c][n][sub].items():
                            for m_ in ("accuracy", "confident_share", "confident_error_rate", "group_all_right"):
                                a, b = res["cells"][p][c][n][sub][lv][m_], cell[m_]
                                if a is None or b is None:
                                    assert a is None and b is None, (p, c, n, sub, lv, m_)
                                else:
                                    worst = max(worst, abs(a - b))
            for c in F3.CONDS3:
                for lv in LEVELS:
                    for m_ in ("accuracy", "confident_share"):
                        worst = max(worst, abs(res["cells"][p][c]["rel v4"]["all"][lv][m_] -
                                               r4[p][c]["rel v4"]["all"][lv][m_]))
        res["report"]["dev_reproduction_max_difference"] = worst
        assert worst < 1e-12, f"dev cells do not reproduce the stored step-4/5 results (max diff {worst})"
        print(f"dev reproduction: max difference {worst:.2e}", flush=True)
    cands, specs = candidate_claims(Q, wins)
    cands = judge_all(cands)
    if split == "dev":
        key = [k for k in cands if any(k.startswith(p + ":") for p in KEY)]
    else:                                                # mark the registered claims (registration 3)
        reg = json.load(open(CLAIMS_OUT))
        assert set(reg["registered"]) <= set(cands), "a registered claim was not computed"
        for k, c in cands.items():
            c["registered"] = k in reg["registered"]
        key = reg["key"]
    for k in key:                                        # report-only sensitivity (registration 4): Bonferroni
        cands[k]["key"] = True
        cands[k]["ci_bonferroni"] = boot_joint(*specs[k], n=10 * N_BOOT, alpha=0.05 / len(key))
    groups_ = collections.defaultdict(collections.Counter)
    for k, c in cands.items():
        if split == "dev" or c.get("registered"):
            groups_[k.split()[0]][c["verdict"]] += 1
    res["summary"] = {"key": {k: cands[k]["verdict"] for k in key},
                      "by group": {g: dict(v) for g, v in sorted(groups_.items())}}
    print("key claims:", dict(collections.Counter(cands[k]["verdict"] for k in key)), flush=True)
    print("by group:", json.dumps(res["summary"]["by group"]), flush=True)
    res["claims"] = cands
    dep = {}
    for p in ("r_hear", "s_move"):
        for c in ("D_off_none", "C_off_fake", "C05_off_fake", "T_off_truth"):
            for lv in LEVELS:
                xs = Q[(p, c, "rel v5", lv, "all")]
                dz = np.array([abs(dep_of[(lv, c, x[7], x[2])]) for x in xs])
                dep[f"{p} {c} {lv}"] = {"mean |z - z0|": float(dz.mean()), "share > 0.5": float(np.mean(dz > 0.5))}
    res["report"]["label_dependence"] = dep
    res["report"]["seconds"] = round(time.time() - t0)
    json.dump(res, open(path, "w"), indent=1, default=float)
    for k, c in cands.items():
        extra = {a: (round(b, 3) if isinstance(b, float) else b) for a, b in c.items()
                 if a not in ("point", "ci95", "bar", "higher", "verdict")}
        ci = "n/a" if c["ci95"] is None else f"[{c['ci95'][0]:+.3f}, {c['ci95'][1]:+.3f}]"
        pt = "n/a" if c["point"] is None else f"{c['point']:+.3f}"
        print(f"{c['verdict']:14s} {k}: {pt} {ci} {json.dumps(extra)}", flush=True)
    print(f"-> {path} ({time.time() - t0:.0f} s)")


# ------------------------------------------------------------------------------------------------ registration

CLAIMS_OUT = "results/main_v04/reliability_registration_claims.json"
# the key claims (registration 3, marked as key); every other registered claim is reported the same way
KEY = ("M1 r_hear dnoise20", "M1 r_hear dnoise30", "M1 r_hear dnoise40", "M1 s_move dnoise20",
       "M1 s_move dnoise30", "M1 s_move dnoise40", "M2 r_hear D_off_none dnoise40", "M2 s_move D_off_none dnoise40",
       "V4a r_hear dnoise40", "V4b r_hear D_off_none", "V5s r_hear C_off_fake", "TD1 r_hear C_off_fake",
       "TD1 r_hear T_off_truth", "TD2 r_hear C_off_fake", "TD2 r_hear T_off_truth", "V5n s_move A_on_none dnoise40",
       "V5n s_move B_on_fake dclean", "V5n r_hear A_on_none dnoise40", "V5k r_hear knock A_on_none dnoise40")


def register():
    """The registered claims = the dev candidates whose interval lies on the passing side (registration 3)."""
    import p1v4_freeze as FZ
    if os.path.exists(CLAIMS_OUT):
        raise SystemExit(f"{CLAIMS_OUT} exists: the registration is written once")
    src = "results/main_v04/reliability_confirm_dev.json"
    cands = json.load(open(src))["claims"]
    reg = [k for k, c in cands.items() if c["verdict"] == "confirmed"]
    key = [k for k in reg if any(k.startswith(p + ":") for p in KEY)]
    missing = [p for p in KEY if not any(k.startswith(p + ":") for k in reg)]
    if missing:
        raise SystemExit(f"key claims not confirmed on dev: {missing}")
    json.dump({"from": src, "sha256": FZ.sha256(src), "rule": "dev 95% interval wholly on the passing side",
               "registered": reg, "key": key,
               "not_registered": {k: c["verdict"] for k, c in cands.items() if k not in reg}},
              open(CLAIMS_OUT, "w"), indent=1)
    print(f"{CLAIMS_OUT}: {len(reg)} registered ({len(key)} key), {len(cands) - len(reg)} not registered")


# ------------------------------------------------------------------------------------------------ freeze

FREEZE_OUT = "results/main_v04/reliability_confirm_freeze.json"


def freeze():
    """Hashes of every script, model and threshold file the confirmation reads (registration 1); never overwritten."""
    import subprocess
    import p1v4_freeze as FZ
    import p1v4_readout_2d as R2D
    if os.path.exists(FREEZE_OUT):
        raise SystemExit(f"{FREEZE_OUT} exists: the confirmation freeze record is written once")
    if not FZ.git_clean():
        raise SystemExit("commit everything first: the working tree has uncommitted changes")
    files = sorted(FZ.local_modules(["p1v4_reliability_confirm"]))      # already "scripts/<name>.py" (review 3)
    files += [f"{R2D.OUT}/readouts_2d.npz", os.path.join(FIX2.OUT, "clarity_probe.npz"),
              os.path.join(F4.OUT, "models4.json"), os.path.join(F5.OUT, "models5.json"),
              os.path.join(F5.OUT, "words.pkl"), f"{R}/l1/l1_new.pt", FZ.REHEARSAL,
              "docs/p1_v04_reliability_registration.md", "docs/p1_v04_freeze_amendment.md",
              "results/main_v04/reliability_confirm_dev.json", CLAIMS_OUT]
    rec = {"time": time.strftime("%Y-%m-%d %H:%M:%S"),
           "git_commit": subprocess.run(["git", "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip(),
           "files": {f.replace("\\", "/"): {"sha256": FZ.sha256(f), "bytes": os.path.getsize(f)} for f in files}}
    json.dump(rec, open(FREEZE_OUT, "w"), indent=1)
    print(f"{FREEZE_OUT}: {len(files)} files")


def check_freeze():
    import p1v4_freeze as FZ
    rec = json.load(open(FREEZE_OUT))
    bad = [f for f, v in rec["files"].items()
           if not os.path.exists(f) or os.path.getsize(f) != v["bytes"] or FZ.sha256(f) != v["sha256"]]
    if bad:
        raise SystemExit(f"confirmation freeze record mismatch: {bad}")


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    if len(sys.argv) == 3 and sys.argv[2] != "dev" and cmd in ("front", "groups", "forward", "eval"):
        check_freeze()                                   # the frozen files must hold before fresh data is opened
    if cmd == "freeze":
        freeze()
    elif cmd == "check-texts":
        check_texts("dev")
    elif cmd == "rehearse":
        rehearse()
    elif cmd == "register":
        register()
    elif cmd == "front" and len(sys.argv) == 3:
        front(sys.argv[2])
    elif cmd == "groups" and len(sys.argv) == 3:
        groups_cmd(sys.argv[2])
    elif cmd == "render" and len(sys.argv) >= 4:
        if sys.argv[2] != "dev":
            check_freeze()
        render(sys.argv[2], sys.argv[3:])
    elif cmd == "forward" and len(sys.argv) == 3:
        forward(sys.argv[2])
    elif cmd == "eval" and len(sys.argv) == 3:
        eval_(sys.argv[2])
    else:
        raise SystemExit(__doc__)
